content:
[toc]
类(Class)类定义class className &#123;    /* All member variables  and member functions*/&#125;; // 注意，类定义必须以分号结尾

创建对象
class className &#123;  ...&#125;;int main() &#123;  int i; //integer object  className c; // className object&#125;

类访问范围私有：
class Class1 &#123;  int num; // 1. 默认时私有的  ...&#125;;class Class2 &#123;  private: // 也可以显示声明私有  int num;  ...&#125;;

public &amp; protected
class myClass &#123;  int num = 1; // 私有变量  protected:  int count = 0; // 保护类型    public: // 共有  void setNum()&#123;  &#125;&#125;;

类方法类方法技能在类中直接定义，也可以先在类中声明，再在类外定义：
class Rectangle &#123;  int length;  int width;  public:  void setLength(int l)&#123; // 类中定义    length = l;  &#125;    int area()&#123;    return length * width; // 定义并且返回值  &#125;&#125;; // 注意分号

范围操作符::用于在类定义的外部定义类方法
class Rectangle &#123;  int length;  int width;  public:    // 1. 此处仅声明  void setLength(int l);  int area();&#125;;// 2. 使用范围操作符来定义方法void Rectangle::setLength(int l)&#123;  length = l;&#125;int Rectangle::area()&#123;  return length * width; &#125;

构造器#include &lt;iostream&gt;#include &lt;string&gt;using namespace std;class Date &#123;  int day;  int month;  int year;  public:  // 默认构造器  Date()&#123;    // 定义默认的值    day = 0;    month = 0;    year = 0;  &#125;  // 函数  void printDate()&#123;     cout &lt;&lt; &quot;Date: &quot; &lt;&lt; day &lt;&lt; &quot;/&quot; &lt;&lt; month &lt;&lt; &quot;/&quot; &lt;&lt; year &lt;&lt; endl;  &#125;&#125;;int main()&#123;  // 创建类对象  Date d; // 使用默认构造器创建对象  d.printDate();&#125;

this指针，this表示当前对象的指针。
#include &lt;iostream&gt;#include &lt;string&gt;using namespace std;class Date &#123;  int day;  int month;  int year;  public:  // 默认构造函数  Date()&#123;    // We must define the default values for day, month, and year    day = 0;    month = 0;    year = 0;  &#125;    // 参数构造函数  Date(int day, int month, int year)&#123;    // 使用指针    this-&gt;day = day;    this-&gt;month = month;    this-&gt;year = year;  &#125;  // A simple print function  void printDate()&#123;     cout &lt;&lt; &quot;Date: &quot; &lt;&lt; day &lt;&lt; &quot;/&quot; &lt;&lt; month &lt;&lt; &quot;/&quot; &lt;&lt; year &lt;&lt; endl;  &#125;&#125;;int main()&#123;  // 调用参数构造函数    Date d(1, 8, 2018); // 使用指定的参数值创建对象  d.printDate();&#125;

1. Java链接数据库import java.sql.Connection;import java.sql.DriverManager;import java.sql.ResultSet;import java.sql.SQLException;import java.sql.Statement;import java.util.List;import java.util.ArrayList;public class JdbcMain &#123;  public static void main(String[] args) throws ClassNotFoundException &#123;    // TODO: Load the SQLite JDBC driver (JDBC class implements java.sql.Driver)    Class.forName(&quot;org.sqlite.JDBC&quot;);    // TODO: Create a DB connection    try(Connection connection = DriverManager.getConnection(&quot;jdbc:sqlite:contactmgr.db&quot;)) &#123;            // TODO: Create a SQL statement      Statement statement = connection.createStatement();            // TODO: Create a DB table      statement.executeUpdate(&quot;DROP TABLE IF EXISTS contacts&quot;);      statement.executeUpdate(&quot;CREATE TABLE contacts (id INTEGER PRIMARY KEY, firstname STRING, lastname STRING, email STRING, phone INT(10))&quot;);            // TODO: Insert a couple contacts      statement.executeUpdate(&quot;INSERT INTO contacts (firstname, lastname, email, phone) VALUES(&#x27;Liu&#x27;, &#x27;Lixiang&#x27;, &#x27;liulixiang1988@gmail.com&#x27;, 1234567890)&quot;);      statement.executeUpdate(&quot;INSERT INTO contacts (firstname, lastname, email, phone) VALUES(&#x27;Long&#x27;, &#x27;Long&#x27;, &#x27;abc@gmail.com&#x27;, 0987654321)&quot;);            // TODO: Fetch all the records from the contacts table      ResultSet rs = statement.executeQuery(&quot;SELECT * FROM contacts&quot;);            // TODO: Iterate over the ResultSet &amp; display contact info      while(rs.next())&#123;        int id = rs.getInt(&quot;id&quot;);        String firstName = rs.getString(&quot;firstname&quot;);        String lastName = rs.getString(&quot;lastname&quot;);                System.out.printf(&quot;%s %s (%d)&quot;, firstName, lastName, id);      &#125;          &#125; catch (SQLException ex) &#123;      // Display connection or query errors      System.err.printf(&quot;There was a database error: %s%n&quot;,ex.getMessage());    &#125;  &#125;&#125;

编译：javac JdbcMain.java
运行：java -cp sqlite-jdbc.3.8.6.jar:. JdbcMain
2 Hibernate入门2.1 创建一个使用Hibernate的项目创建gradle项目contactmgr-hibernate项目,并修改build.gradle:
dependencies &#123;    compile &#x27;org.hibernate:hibernate-core:5.1.0.Final&#x27;    compile &#x27;com.h2database:h2:1.4.191&#x27;&#125;

在根目录创建data文件夹，用来存放h2文件数据库。
在resources目录下创建hibernate.cfg.xml，这个文件用来保存SessionFactory的配置：
&lt;hibernate-configuration&gt;    &lt;session-factory&gt;        &lt;!--数据库链接配置--&gt;        &lt;property name=&quot;connection.driver_class&quot;&gt;org.h2.Driver&lt;/property&gt;        &lt;property name=&quot;connection.url&quot;&gt;jdbc:h2:./data/contactmgr&lt;/property&gt;        &lt;!--SQL 方言--&gt;        &lt;property name=&quot;dialect&quot;&gt;org.hibernate.dialect.H2Dialect&lt;/property&gt;    &lt;/session-factory&gt;&lt;/hibernate-configuration&gt;

2.2 使用JPA注解添加POJO添加包io.github.liulixiang1988.contactmgr，并在其中创建Application类：
package io.github.liulixiang1988.contactmgr;public class Application &#123;    public static void main(String[] args) &#123;    &#125;&#125;

然后在contactmgr中创建model包，并创建Contact类：
package io.github.liulixiang1988.contactmgr.model;import javax.persistence.*;@Entity //映射为表public class Contact &#123;    @Id //主键    @GeneratedValue(strategy = GenerationType.IDENTITY) //自增长    private int id;    @Column    private String firstName;    @Column    private String lastName;    @Column    private String email;    @Column    private Long phone;    // 为JPA准备的    public Contact()&#123;&#125;    @Override    public String toString() &#123;        return &quot;Contact&#123;&quot; +                &quot;id=&quot; + id +                &quot;, firstName=&#x27;&quot; + firstName + &#x27;\&#x27;&#x27; +                &quot;, lastName=&#x27;&quot; + lastName + &#x27;\&#x27;&#x27; +                &quot;, email=&#x27;&quot; + email + &#x27;\&#x27;&#x27; +                &quot;, phone=&quot; + phone +                &#x27;&#125;&#x27;;    &#125;    public int getId() &#123;        return id;    &#125;    public void setId(int id) &#123;        this.id = id;    &#125;    public String getFirstName() &#123;        return firstName;    &#125;    public void setFirstName(String firstName) &#123;        this.firstName = firstName;    &#125;    public String getLastName() &#123;        return lastName;    &#125;    public void setLastName(String lastName) &#123;        this.lastName = lastName;    &#125;    public String getEmail() &#123;        return email;    &#125;    public void setEmail(String email) &#123;        this.email = email;    &#125;    public Long getPhone() &#123;        return phone;    &#125;    public void setPhone(Long phone) &#123;        this.phone = phone;    &#125;&#125;

然后我们修改hibernate.cfg.xml来为model做一些配置：
&lt;hibernate-configuration&gt;    &lt;session-factory&gt;        &lt;!--...--&gt;        &lt;!--启动时创建数据结构--&gt;        &lt;property name=&quot;hbm2ddl.auto&quot;&gt;create&lt;/property&gt;        &lt;!--为标识的实体类命名--&gt;        &lt;mapping class=&quot;io.github.liulixiang1988.contactmgr.model.Contact&quot;/&gt;    &lt;/session-factory&gt;&lt;/hibernate-configuration&gt;

2.3 创建Hibernate SessionFactorypublic class Application &#123;    //保存一个SessionFactory(我们也只需要一个)    private static final SessionFactory sessionFactory = buildSessionFactory();    private static SessionFactory buildSessionFactory() &#123;        //创建StandardServiceRegistry        final ServiceRegistry registry = new StandardServiceRegistryBuilder().configure().build();        return new MetadataSources(registry).buildMetadata().buildSessionFactory();    &#125;    public static void main(String[] args) &#123;    &#125;&#125;

2.4 Builder模式修改Contact.java
public class Contact &#123;        //...    @Override    public String toString() &#123;        return &quot;Contact&#123;&quot; +                &quot;id=&quot; + id +                &quot;, firstName=&#x27;&quot; + firstName + &#x27;\&#x27;&#x27; +                &quot;, lastName=&#x27;&quot; + lastName + &#x27;\&#x27;&#x27; +                &quot;, email=&#x27;&quot; + email + &#x27;\&#x27;&#x27; +                &quot;, phone=&quot; + phone +                &#x27;&#125;&#x27;;    &#125;    //...    public static class ContactBuilder &#123;        private String firstName;        private String lastName;        private String email;        private Long phone;        public ContactBuilder(String firstName, String lastName) &#123;            this.firstName = firstName;            this.lastName = lastName;        &#125;        public ContactBuilder withEmail(String email) &#123;            this.email = email;            return this;        &#125;        public ContactBuilder withPhone(Long phone) &#123;            this.phone = phone;            return this;        &#125;        public Contact build() &#123;            return new Contact(this);        &#125;    &#125;&#125;

修改Application.java:
public static void main(String[] args) &#123;    Contact contact = new ContactBuilder(&quot;Chris&quot;,&quot;Ramacciotti&quot;)            .withEmail(&quot;rama@teamtreehouse.com&quot;)            .withPhone(7735556666L)            .build();&#125;

3. 使用Hibernate存取数据要让Hibernate支持存取数据，需要添加依赖：
compile &#x27;javax.transaction:jta:1.1&#x27;

为了能看到Hibernate准备的查询，我们设置：
&lt;property name=&quot;show_sql&quot;&gt;true&lt;/property&gt;

3.1 添加数据public static void main(String[] args) &#123;    Contact contact = new ContactBuilder(&quot;Chris&quot;,&quot;Ramacciotti&quot;)            .withEmail(&quot;rama@teamtreehouse.com&quot;)            .withPhone(7735556666L)            .build();    //打开session    Session session = sessionFactory.openSession();    //begin transaction    session.beginTransaction();    //使用session来保存对象    session.save(contact);    //提交session    session.getTransaction().commit();    //关闭session    session.close();&#125;

3.2 查询数据@SuppressWarnings(&quot;unchecked&quot;)private static List&lt;Contact&gt; fetchAllContact() &#123;    Session session = sessionFactory.openSession();    //创建Criteria    Criteria criteria = session.createCriteria(Contact.class);    //从Criteria中获取数据    List&lt;Contact&gt; contacts = criteria.list();    //关闭会话    session.close();    return contacts;&#125;

调用可以使用java8的特性，而非使用for循环：
fetchAllContact().stream().forEach(System.out::println);

可以通过修改hibernate.cfg.xml，让每次启动时是更新而不是创建数据库：
&lt;property name=&quot;hbm2ddl.auto&quot;&gt;update&lt;/property&gt;

3.3 更新与删除private static Contact findContactById(int id) &#123;    //打开会话    Session session = sessionFactory.openSession();    //获取对象或者null    Contact contact = session.get(Contact.class, id);    //关闭会话    session.close();    //返回对象    return contact;&#125;private static void update(Contact contact) &#123;    Session session = sessionFactory.openSession();    session.beginTransaction();    session.update(contact);    session.getTransaction().commit();    session.close();&#125;private static void delete(Contact contact) &#123;    Session session = sessionFactory.openSession();    session.beginTransaction();    session.delete(contact);    session.getTransaction().commit();    session.close();&#125;

1. JDBC编程步骤加载驱动程序：
Class.forName(driverClass)//加载MySql驱动Class.forName(&quot;com.mysql.jdbc.Driver&quot;)//加载Oracle驱动Class.forName(&quot;oracle.jdbc.driver.OracleDriver&quot;)

获得数据库连接：
DriverManager.getConnection(&quot;jdbc:mysql://127.0.0.1:3306/imooc&quot;, &quot;root&quot;, &quot;root&quot;);

创建Statement\PreparedStatement对象：
conn.createStatement();conn.prepareStatement(sql);

例子：
import java.sql.Connection;import java.sql.DriverManager;import java.sql.ResultSet;import java.sql.Statement;public class DbUtil &#123;    public static final String URL = &quot;jdbc:mysql://localhost:3306/imooc&quot;;    public static final String USER = &quot;liulx&quot;;    public static final String PASSWORD = &quot;123456&quot;;    public static void main(String[] args) throws Exception &#123;        //1.加载驱动程序        Class.forName(&quot;com.mysql.jdbc.Driver&quot;);        //2. 获得数据库连接        Connection conn = DriverManager.getConnection(URL, USER, PASSWORD);        //3.操作数据库，实现增删改查        Statement stmt = conn.createStatement();        ResultSet rs = stmt.executeQuery(&quot;SELECT user_name, age FROM imooc_goddess&quot;);        //如果有数据，rs.next()返回true        while(rs.next())&#123;            System.out.println(rs.getString(&quot;user_name&quot;)+&quot; 年龄：&quot;+rs.getInt(&quot;age&quot;));        &#125;    &#125;&#125;

2. 增删改查public class DbUtil &#123;    public static final String URL = &quot;jdbc:mysql://localhost:3306/imooc&quot;;    public static final String USER = &quot;liulx&quot;;    public static final String PASSWORD = &quot;123456&quot;;    private static Connection conn = null;    static&#123;        try &#123;            //1.加载驱动程序            Class.forName(&quot;com.mysql.jdbc.Driver&quot;);            //2. 获得数据库连接            conn = DriverManager.getConnection(URL, USER, PASSWORD);        &#125; catch (ClassNotFoundException e) &#123;            e.printStackTrace();        &#125; catch (SQLException e) &#123;            e.printStackTrace();        &#125;    &#125;    public static Connection getConnection()&#123;        return conn;    &#125;&#125;//模型package liulx.model;import java.util.Date;public class Goddess &#123;    private Integer id;    private String user_name;    private Integer sex;    private Integer age;    private Date birthday; //注意用的是java.util.Date    private String email;    private String mobile;    private String create_user;    private String update_user;    private Date create_date;    private Date update_date;    private Integer isDel;    //getter setter方法。。。&#125;//---------dao层--------------package liulx.dao;import liulx.db.DbUtil;import liulx.model.Goddess;import java.sql.Connection;import java.sql.ResultSet;import java.sql.SQLException;import java.sql.Statement;import java.util.ArrayList;import java.util.List;public class GoddessDao &#123;    //增加    public void addGoddess(Goddess g) throws SQLException &#123;        //获取连接        Connection conn = DbUtil.getConnection();        //sql        String sql = &quot;INSERT INTO imooc_goddess(user_name, sex, age, birthday, email, mobile,&quot;+            &quot;create_user, create_date, update_user, update_date, isdel)&quot;                +&quot;values(&quot;+&quot;?,?,?,?,?,?,?,CURRENT_DATE(),?,CURRENT_DATE(),?)&quot;;        //预编译        PreparedStatement ptmt = conn.prepareStatement(sql); //预编译SQL，减少sql执行        //传参        ptmt.setString(1, g.getUser_name());        ptmt.setInt(2, g.getSex());        ptmt.setInt(3, g.getAge());        ptmt.setDate(4, new Date(g.getBirthday().getTime()));        ptmt.setString(5, g.getEmail());        ptmt.setString(6, g.getMobile());        ptmt.setString(7, g.getCreate_user());        ptmt.setString(8, g.getUpdate_user());        ptmt.setInt(9, g.getIsDel());        //执行        ptmt.execute();    &#125;    public void updateGoddess()&#123;        //获取连接        Connection conn = DbUtil.getConnection();        //sql, 每行加空格        String sql = &quot;UPDATE imooc_goddess&quot; +                &quot; set user_name=?, sex=?, age=?, birthday=?, email=?, mobile=?,&quot;+                &quot; update_user=?, update_date=CURRENT_DATE(), isdel=? &quot;+                &quot; where id=?&quot;;        //预编译        PreparedStatement ptmt = conn.prepareStatement(sql); //预编译SQL，减少sql执行        //传参        ptmt.setString(1, g.getUser_name());        ptmt.setInt(2, g.getSex());        ptmt.setInt(3, g.getAge());        ptmt.setDate(4, new Date(g.getBirthday().getTime()));        ptmt.setString(5, g.getEmail());        ptmt.setString(6, g.getMobile());        ptmt.setString(7, g.getUpdate_user());        ptmt.setInt(8, g.getIsDel());        ptmt.setInt(9, g.getId());        //执行        ptmt.execute();    &#125;    public void delGoddess()&#123;        //获取连接        Connection conn = DbUtil.getConnection();        //sql, 每行加空格        String sql = &quot;delete from imooc_goddess where id=?&quot;;        //预编译SQL，减少sql执行        PreparedStatement ptmt = conn.prepareStatement(sql);        //传参        ptmt.setInt(1, id);        //执行        ptmt.execute();    &#125;    public List&lt;Goddess&gt; query() throws SQLException &#123;        Connection conn = DbUtil.getConnection();        Statement stmt = conn.createStatement();        ResultSet rs = stmt.executeQuery(&quot;SELECT user_name, age FROM imooc_goddess&quot;);        List&lt;Goddess&gt; gs = new ArrayList&lt;Goddess&gt;();        Goddess g = null;        while(rs.next())&#123;            g = new Goddess();            g.setUser_name(rs.getString(&quot;user_name&quot;));            g.setAge(rs.getInt(&quot;age&quot;));            gs.add(g);        &#125;        return gs;    &#125;    public Goddess get()&#123;        Goddess g = null;        //获取连接        Connection conn = DbUtil.getConnection();        //sql, 每行加空格        String sql = &quot;select * from  imooc_goddess where id=?&quot;;        //预编译SQL，减少sql执行        PreparedStatement ptmt = conn.prepareStatement(sql);        //传参        ptmt.setInt(1, id);        //执行        ResultSet rs = ptmt.executeQuery();        while(rs.next())&#123;            g = new Goddess();            g.setId(rs.getInt(&quot;id&quot;));            g.setUser_name(rs.getString(&quot;user_name&quot;));            g.setAge(rs.getInt(&quot;age&quot;));            g.setSex(rs.getInt(&quot;sex&quot;));            g.setBirthday(rs.getDate(&quot;birthday&quot;));            g.setEmail(rs.getString(&quot;email&quot;));            g.setMobile(rs.getString(&quot;mobile&quot;));            g.setCreate_date(rs.getDate(&quot;create_date&quot;));            g.setCreate_user(rs.getString(&quot;create_user&quot;));            g.setUpdate_date(rs.getDate(&quot;update_date&quot;));            g.setUpdate_user(rs.getString(&quot;update_user&quot;));            g.setIsDel(rs.getInt(&quot;isdel&quot;));        &#125;        return g;    &#125;&#125;

1. JavaBean简介javaBeans就是符合某种特定的规范的java类。使用JavaBeans的好处是解决代码重复编写，减少代码冗余，功能区分明确，提高了代码的可维护性。
JavaBean的设计原则：

公有类
属性私有
无参的公有构造方法
getter和setter方法

2. JSP动作元素2.1 什么是JSP动作元素JSP动作元素（action element），动作元素为请求处理阶段提供信息。动作元素遵循XML语法，有一个包含元素名的开始标签，可以有属性，可选的内容、与开始标签匹配的结束标签。
2.2 JSP动作元素的五大类第一类是与存取JavaBean有关的，包括：&lt;jsp:useBean&gt; &lt;jsp:setProperty&gt; &lt;jsp:getProperty&gt;
第二类是JSP1.2就开始有的基本元素，包括6个动作元素：&lt;jsp:include&gt; &lt;jsp:forward&gt; &lt;jsp:param&gt; &lt;jsp:plugin&gt; &lt;jsp:params&gt; &lt;jsp:fallback&gt;
第三类是JSP2.0新增的元素，主要与JSP Document有关，包括6个元素：&lt;jsp:root&gt; &lt;jsp:declaration&gt; &lt;jsp:scriptlet&gt; &lt;jsp:expression&gt; &lt;jsp:text&gt; &lt;jsp:output&gt;
第四类是JSP2.0新增的动作元素，主要是用来动态生成XML元素标签的值，包括三个动作：&lt;jsp:attribute&gt; &lt;jsp:body&gt;  &lt;jsp:element&gt;
第五类是JSP2.0新增的动作元素，主要是用在Tag File中，有2个元素：&lt;jsp:invoke&gt; &lt;jsp:dobody&gt;
3. 如何在JSP中使用Java  Beans3.1 像使用普通java类一样
创建在src文件下，（可以创建包）创建一个类，满足设计原则即可
使用前通过import导入，通过使用new创建Javabean实例.在顶端添加&lt;%@ page import=&quot;com.po.Users&quot; %&gt;，导入javabean包

3.2 useBean元素在JSP页面中通常使用JSP动作标签使用javabean(useBeans动作、setProperty动作、getProperty动作)&lt;jsp:useBeans&gt;作用：在jsp页面中实例化或者在指定范围内使用javabean:&lt;jsp:useBean id=&quot;标识符&quot; class=&quot;Java类名&quot; scope=&quot;作用范围&quot;/&gt;
3.3 使用setProperty&lt;jsp:setProperty&gt;动作：给【已经实例化的Javabean对象的属性赋值】，一共有四种形式。

根据表单自动匹配所有的属性&lt;jsp:setProperty name=&quot;myUsers&quot; property=&quot;*&quot;/&gt;
根据表单自动匹配相应的属性（部分匹配）&lt;jsp:setProperty name=&quot;myUsers&quot; property=&quot;username&quot;/&gt;
与表单无关，通过手工赋值给属性&lt;jsp:setProperty name=&quot;myUsers&quot; property=&quot;username&quot; value=“Lisa”/&gt;
通过url传参数给属性赋值

&lt;jsp:setProperty name=&quot;myUsers&quot; property=&quot;username&quot;/&gt;&lt;jsp:setProperty name=&quot;myUsers&quot; property=&quot;password&quot; param=“mypass”/&gt;

案例：表单部分：
&lt;form action=&quot;dologin.jsp&quot; method=&quot;post&quot;&gt;  &lt;table&gt;    &lt;tr&gt;      &lt;td&gt;用户名&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;text&quot; name=&quot;username&quot;/&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;密码&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;password&quot; name=&quot;password&quot;/&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td colspan=&quot;2&quot;&gt;&lt;input type=&quot;submit&quot; value=&quot;提交&quot;/&gt;&lt;/td&gt;    &lt;/tr&gt;  &lt;/table&gt;&lt;/form&gt;

dologin.jsp中匹配：
&lt;h1&gt;根据表单自动匹配所有属性&lt;/h1&gt;&lt;hr/&gt;&lt;jsp:useBean id=&quot;myUsers&quot; class=&quot;liulx.javabean.User&quot; scope=&quot;page&quot; /&gt;&lt;%request.setCharacterEncoding(&quot;utf-8&quot;);%&gt;&lt;jsp:setProperty name=&quot;myUsers&quot; property=&quot;*&quot; /&gt;用户名：&lt;%=myUsers.getUsername()%&gt;密码：&lt;%=myUsers.getPassword()%&gt;

###3.4 getProperty标签
&lt;jsp:getProperty&gt;动作：获取指定Javabean对象的属性值
&lt;jsp:getProperty name=&quot;JavaBean实例名&quot; property=&quot;属性名&quot; /&gt;可以直接得到值
用户名：&lt;jsp:getProperty name=&quot;myUsers&quot; property=&quot;username&quot; /&gt;

4. JavaBean四个作用域范围使用useBeans的scope属性来置顶javabean的作用范围，由小到大排列是：page-&gt;request-&gt;session-&gt;application

page对象仅在当前页面有效
request &#x2F;&#x2F;可以通过HttpRequest.getAttribute()方法取得JavaBean对象.需要配合请求转发来使用，若使用请求重定向则无法访问到Javabean
session &#x2F;&#x2F;可以通过HttpSession.getAttribute()方法取得JavaBean对象则是在一次对话中都会有效
application&#x2F;&#x2F;可以通过application.getAttribute()方法取得JavaBean对象。全局，在服务器一次运行期间都有效

request在源页面用request.getRequestDispatcher(“&#x2F;somePage.jsp”).forward(request, response); 内部转发的方式将数据传递到下一个页面可获取对象。
5. Model1简介Model 1模型出现前，整个Web应用的情况：几乎全部由JSP页面组成，JSP页面接收处理客户端请求，对请求处理后直接做出响应。这样做的弊端：在页面层充斥着大量的业务逻辑代码和数据访问层代码，Web程序的可扩展性和可维护性非常差。
5.1 javaWeb应用开发，模式分为Model1和Model2
Model1早于Model2
在Model1之前，整个Web应用的情况：几乎全部由jsp页组成，jsp处理和响应客户端请求。· 弊端：【界面层】充斥了大量业务逻辑代码和数据访问层代码，扩展性和维护性非常差

5.2 Model1
Javabean的出现，可以使jsp页面使用Javabean封装的数据和业务逻辑代码，大大提高程序可维护性。
Model1 &#x3D; JSP + JavaBean。如图：JSP访问页面层 -&gt; Javab业务逻辑层 -&gt; 数据库数据访问层

