        PreparedStatement stmt = null;        ResultSet rs = null;        try &#123;            conn = DBHelper.getConnection();            String sql = &quot;select * from items where id=?;&quot;; // SQL语句            stmt = conn.prepareStatement(sql);            stmt.setInt(1, id);            rs = stmt.executeQuery();            if (rs.next()) &#123;                Items item = new Items();                item.setId(rs.getInt(&quot;id&quot;));                item.setName(rs.getString(&quot;name&quot;));                item.setCity(rs.getString(&quot;city&quot;));                item.setNumber(rs.getInt(&quot;number&quot;));                item.setPrice(rs.getInt(&quot;price&quot;));                item.setPicture(rs.getString(&quot;picture&quot;));                return item;            &#125; else &#123;                return null;            &#125;        &#125; catch (Exception ex) &#123;            ex.printStackTrace();            return null;        &#125; finally &#123;            // 释放数据集对象            if (rs != null) &#123;                try &#123;                    rs.close();                    rs = null;                &#125; catch (Exception ex) &#123;                    ex.printStackTrace();                &#125;            &#125;            // 释放语句对象            if (stmt != null) &#123;                try &#123;                    stmt.close();                    stmt = null;                &#125; catch (Exception ex) &#123;                    ex.printStackTrace();                &#125;            &#125;        &#125;    &#125;    //获取最近浏览的前五条商品信息    public ArrayList&lt;Items&gt; getViewList(String list)    &#123;        System.out.println(&quot;list:&quot;+list);        ArrayList&lt;Items&gt; itemlist = new ArrayList&lt;Items&gt;();        int iCount=5; //每次返回前五条记录        if(list!=null&amp;&amp;list.length()&gt;0)        &#123;            String[] arr = list.split(&quot;,&quot;);            System.out.println(&quot;arr.length=&quot;+arr.length);            //如果商品记录大于等于5条            if(arr.length&gt;=5)            &#123;               for(int i=arr.length-1;i&gt;=arr.length-iCount;i--)               &#123;                  itemlist.add(getItemsById(Integer.parseInt(arr[i])));                 &#125;            &#125;            else            &#123;                for(int i=arr.length-1;i&gt;=0;i--)                &#123;                    itemlist.add(getItemsById(Integer.parseInt(arr[i])));                &#125;            &#125;            return itemlist;        &#125;        else        &#123;            return null;        &#125;            &#125;&#125;

