@RunWith(SpringJUnit4ClassRunner.class)@ContextConfiguration(classes = AppConfig.class)@Transactional@ActiveProfiles(&quot;test&quot;)public class JdbcAccountRepositoryTest &#123;    @Autowired    private AccountRepository repository;    @Test    public void getAccounts() throws Exception &#123;        List&lt;Account&gt; accounts = repository.getAccounts();        //1. 比较        assertThat(accounts.size(), is(3));    &#125;    @Test    public void getAccount() throws Exception &#123;        Account account = repository.getAccount(1L);        assertThat(account.getId(), is(1L));        //2. 近似        assertThat(new BigDecimal(&quot;100.0&quot;), is(closeTo(account.getBalance(), new BigDecimal(&quot;0.01&quot;))));    &#125;    @Test    public void createAccount() throws Exception &#123;        Long id = repository.createAccount(new BigDecimal(&quot;250.00&quot;));        //3. 非空        assertThat(id, is(notNullValue()));        Account account = repository.getAccount(id);        assertThat(account.getId(), is(id));        assertThat(new BigDecimal(&quot;250.0&quot;), is(closeTo(account.getBalance(), new BigDecimal(&quot;0.01&quot;))));    &#125;    @Test    public void updateAccount() throws Exception &#123;        Account account = repository.getAccount(1L);        BigDecimal current = account.getBalance();        BigDecimal amount = new BigDecimal(&quot;50.0&quot;);        account.setBalance(current.add(amount));        repository.updateAccount(account);        Account again = repository.getAccount(1L);        assertThat(again.getBalance(), is(closeTo(account.getBalance(), new BigDecimal(&quot;0.01&quot;))));    &#125;    @Test    public void deleteAccount() throws Exception &#123;        for (Account account: repository.getAccounts()) &#123;            repository.deleteAccount(account.getId());        &#125;    &#125;&#125;

注意里面的assertThat, is, closeTo等。
现在我们再来看AccountService,它有事务：
@Service @Transactional@Profile(&quot;test&quot;)public class AccountService &#123;    @Autowired    private AccountRepository repository;    @Transactional(readOnly = true, propagation = Propagation.SUPPORTS)    public BigDecimal getBalance(Long id) &#123;        return repository.getAccount(id).getBalance();    &#125;    public BigDecimal deposit(Long id, BigDecimal amount) &#123;        Account account = repository.getAccount(id);        BigDecimal newBalance = account.getBalance().add(amount);        account.setBalance(newBalance);        repository.updateAccount(account);        return newBalance;    &#125;    public BigDecimal withdraw(Long id, BigDecimal amount) &#123;        return deposit(id, amount.negate());    &#125;    public void transfer(Long fromId, Long toId, BigDecimal amount) &#123;        withdraw(fromId, amount);        deposit(toId, amount);    &#125;&#125;

然后我们看看对应的测试：
@RunWith(SpringJUnit4ClassRunner.class)@ContextConfiguration(classes = AppConfig.class)@Transactional@ActiveProfiles(&quot;test&quot;)public class AccountServiceTest &#123;    @Autowired    private AccountService service;    @Test    public void deposit() throws Exception &#123;        BigDecimal start = service.getBalance(1L);        BigDecimal amount = new BigDecimal(&quot;50.0&quot;);        service.deposit(1L, amount);        BigDecimal finish = start.add(amount);        assertThat(finish, is(closeTo(service.getBalance(1L), new BigDecimal(&quot;0.01&quot;))));    &#125;    @Test    public void withdraw() throws Exception &#123;        BigDecimal start = service.getBalance(1L);        BigDecimal amount = new BigDecimal(&quot;50.0&quot;);        service.withdraw(1L, amount);        BigDecimal finish = start.subtract(amount);        assertThat(finish, is(closeTo(service.getBalance(1L), new BigDecimal(&quot;0.01&quot;))));    &#125;    @Test    public void transfer() throws Exception &#123;        BigDecimal acct1start = service.getBalance(1L);        BigDecimal acct2start = service.getBalance(2L);        BigDecimal amount = new BigDecimal(&quot;50.0&quot;);        service.transfer(1L, 2L, amount);        BigDecimal acct1finish = acct1start.subtract(amount);        BigDecimal acct2finish = acct2start.add(amount);        assertThat(acct1finish, is(closeTo(service.getBalance(1L), new BigDecimal(&quot;0.01&quot;))));        assertThat(acct2finish, is(closeTo(service.getBalance(2L), new BigDecimal(&quot;0.01&quot;))));    &#125;&#125;

这里事务运行的没问题。

