7.3 实现JPA Repository现在我们用EntityManagerFactory来实现JPA Repository。
我们来创建AccountRepository接口和JpaAccountRepository类：
package lx.spring.core.repositories;import lx.spring.core.entities.Account;import java.math.BigDecimal;import java.util.List;public interface AccountRepository &#123;    List&lt;Account&gt; getAccounts();    Account getAccount(Long id);    int getNumberOfAccounts();    Long createAccount(BigDecimal initialBalance);    int deleteAccount(Long id);    void updateAccount(Account account);&#125;

package lx.spring.core.repositories;import lx.spring.core.entities.Account;import org.springframework.stereotype.Repository;import javax.persistence.EntityManager;import javax.persistence.PersistenceContext;import java.math.BigDecimal;import java.util.List;@Repositorypublic class JpaAccountRepository implements AccountRepository &#123;    private long nextId = 4;    @PersistenceContext //Spring会注入    private EntityManager entityManager;    @Override    public List&lt;Account&gt; getAccounts() &#123;        return entityManager.createQuery(&quot;select a from Account a&quot;, Account.class).getResultList();    &#125;    @Override    public Account getAccount(Long id) &#123;        return entityManager.find(Account.class, id);    &#125;    @Override    public int getNumberOfAccounts() &#123;        String jpaText = &quot;select count(a.id) from Account a&quot;;        Long result = (Long) entityManager.createQuery(jpaText).getSingleResult();        return result.intValue();    &#125;    @Override    public Long createAccount(BigDecimal initialBalance) &#123;        long id = nextId++;        entityManager.persist(new Account(id, initialBalance));        return id;    &#125;    @Override    public int deleteAccount(Long id) &#123;        entityManager.remove(getAccount(id));        return 1;    &#125;    @Override    public void updateAccount(Account account) &#123;        entityManager.merge(account);    &#125;&#125;

这里我们用的不是标准的SQL，而是JPA表达式。而且像select count(a.id) from Account a这些语句里都是类名和字段名，所以是区分大小写的。
7.4 测试我们创建的测试和上一节类似：
