7.5 Spring Data JPASpring Data JPA能够进一步简化我们的应用。首先我们添加依赖：
compile group: &#x27;org.springframework.data&#x27;, name: &#x27;spring-data-jpa&#x27;, version: &#x27;1.10.2.RELEASE&#x27;

然后我们修改AppConfig.java
@Configuration@ComponentScan(basePackages = &quot;lx.spring.core&quot;)@EnableJpaRepositories(basePackages = &quot;lx.spring.core.repositories&quot;) //这个注解是用来发现spring data jpa的@PropertySource(&quot;classpath:prod.properties&quot;)@EnableTransactionManagementpublic class AppConfig &#123;...&#125;

注意@EnableJpaRepositories注解。
接着，我们修改AccountRepository并删除对应的实现类：
public interface AccountRepository extends JpaRepository&lt;Account, Long&gt;&#123;    List&lt;Account&gt; findAccountsByBalanceGreaterThanEqual(BigDecimal amount);&#125;

注意这里我们继承了JpaRepository，这样就可以了。不需要实现什么。
同时，我们定义了findAccountsByBalanceGreaterThanEqual方法，这个名称是约定的，find表示查找，By后面的是字段，GreaterThanEqual是条件。
此时，我们在测试中调用：
@RunWith(SpringJUnit4ClassRunner.class)@ContextConfiguration(classes=AppConfig.class)@Transactionalpublic class JpaAccountRepositoryTest &#123;    @Autowired    private AccountRepository repository;    @Test    public void getAccounts() throws Exception &#123;        List&lt;Account&gt; accounts = repository.findAll();        assertThat(accounts.size(), is(3));    &#125;    @Test    public void getNumberOfAccounts() throws Exception &#123;        assertThat(repository.count(), is(3));    &#125;    @Test    public void getAccount() throws Exception &#123;        Account account = repository.findOne(1L);        assertThat(account.getId(), is(1L));        //2. 近似        assertThat(new BigDecimal(&quot;100.0&quot;), is(closeTo(account.getBalance(), new BigDecimal(&quot;0.01&quot;))));    &#125;    @Test    public void createAccount() throws Exception &#123;        Account account = new Account(99L, new BigDecimal(&quot;250.00&quot;));        repository.save(account);        Long id = account.getId();        //3. 非空        assertThat(id, is(notNullValue()));        Account again = repository.findOne(id);        assertThat(again.getId(), is(id));        assertThat(new BigDecimal(&quot;250.0&quot;), is(closeTo(account.getBalance(), new BigDecimal(&quot;0.01&quot;))));    &#125;    @Test    public void updateAccount() throws Exception &#123;        Account account = repository.findOne(1L);        BigDecimal current = account.getBalance();        BigDecimal amount = new BigDecimal(&quot;50.0&quot;);        account.setBalance(current.add(amount));        repository.save(account);        Account again = repository.findOne(1L);        assertThat(again.getBalance(), is(closeTo(account.getBalance(), new BigDecimal(&quot;0.01&quot;))));    &#125;    @Test    public void deleteAccount() throws Exception &#123;        repository.deleteAll();        assertThat(repository.count(), is(0L));    &#125;&#125;

