package KotlinSample.demo6interface IFactory&lt;T&gt; &#123;    fun create(): T&#125;//注意,伴随对象并不是真正的static的class Point(var x: Double, var y: Double)&#123;    //伴随对象,使用companion object修饰,其中Factory可以注释掉,也就是下面的代码也是可用的:    //companion object &#123;    //伴随对象还能实现接口    companion object /*Factory*/ : IFactory&lt;Point&gt;&#123;        override fun create(): Point &#123;            return Point(0.0, 0.0)        &#125;        fun createCarterian(x: Double, y: Double): Point = Point(x, y)        fun createPolar(x: Double, y: Double): Point = Point(x, y)    &#125;&#125;fun main(args: Array&lt;String&gt;) &#123;    var simplePoint = Point(1.0, 2.0)    //var factoryPoint = Point.Factory.createCarterian(1.0, 2.0)    //类似静态方法的调用    var factoryPoint2 = Point.createPolar(1.0, 2.0)    var defaultPoint = Point.create()    //或者如果没有给伴随对象起名字,也可以用下面这个方法    var defaultPoint2 = Point.Companion.create()&#125;

5.7 继承(Inheritance)//只有open的class才能被继承open class Person(val name: String)&#123;    //同样只有open方法才能被overwrite    open fun talk()&#123;        println(&quot;I&#x27;m $name&quot;)    &#125;&#125;//父类已经有了name,所以不能再给这里的name添加val/var//Person有构造方法,因此必须对其进行调用class Manager(name: String, var subordinates: List&lt;Person&gt;) : Person(name)&#123;    //重写方法    override fun talk()&#123;        println(&quot;I&#x27;m $name, I have $&#123;subordinates.size&#125; subordinates&quot;)    &#125;&#125;fun main(args: Array&lt;String&gt;) &#123;    val lixiang = Person(&quot;理想&quot;)    lixiang.talk()    val boss = Manager(&quot;龙&quot;, listOf(lixiang))    boss.talk()&#125;

